<script setup lang="ts">import {computed} from 'vue';import {fmt,percent} from '../utils/format';const p=defineProps<{bootstrap:any;grouping?:any}>();const max=computed(()=>Math.max(...p.bootstrap.histogram.counts,1)),cluster=computed(()=>p.bootstrap.resampling_unit==='core_cluster'||p.grouping?.resampling_unit==='core_cluster'),preview=computed<any[]>(()=> (p.bootstrap.replicates||[]).filter((r:any)=>r.sampled_cores).slice(0,16)),groups=computed<any[]>(()=>p.grouping?.core_groups||[]);function multiplicity(r:any){return Object.entries(r.core_multiplicity||{}).map(([core,times])=>core+'×'+times).join('、')}</script><template><section class="bootstrap-strip"><div class="section-head"><h2>{{cluster?'整芯成组重采样，重复抽中保留倍数。':'整试样重采样，保留退化重复。'}}</h2><span>{{bootstrap.valid_repeats}} / {{bootstrap.requested_repeats}} 有效 · {{percent(bootstrap.valid_fraction)}}</span></div><p v-if="cluster">每次有放回抽取 {{bootstrap.source_core_count}} 个岩芯，抽中岩芯携带其全部试样进入重复；同芯重复抽中按倍数保留。点估计仍用原逐票全部试样，不按组大小加权。</p><p v-else>每次有放回抽取完整试样计数行，固定原三人面板；本数据无岩芯字段，按逐试样分析。不按单票抽样，不代表新标记者的不确定性。</p><svg viewBox="0 0 900 205" role="img" aria-label="有效bootstrap κ频数分布"><line x1="35" y1="160" x2="870" y2="160" class="hist-axis"/><g v-for="(count,i) in bootstrap.histogram.counts" :key="i"><rect :x="35+Number(i)*41.75+3" :y="160-Number(count)/max*125" width="35" :height="Number(count)/max*125" class="hist-bar"/><text v-if="count" :x="35+Number(i)*41.75+20" :y="151-Number(count)/max*125" text-anchor="middle">{{count}}</text></g><text x="35" y="190">κ −1</text><text x="452" y="190" text-anchor="middle">0</text><text x="870" y="190" text-anchor="end">1</text></svg><div class="interval-line"><div><small>95%经验percentile区间</small><strong v-if="bootstrap.interval">[{{fmt(bootstrap.interval[0],6)}}, {{fmt(bootstrap.interval[1],6)}}]</strong><strong v-else>暂不报告</strong></div><p>{{bootstrap.interval_reason}}。退化 {{bootstrap.invalid_repeats}} 次，未补抽替换。</p></div><p v-for="(count,reason) in bootstrap.invalid_reasons" :key="reason" class="invalid-reason">{{reason}}：{{count}} 次</p><details><summary>{{cluster?'岩芯分组与前16次重复：抽中岩芯、倍数与试样总数':'前16次重复：行索引、κ和失败理由'}}</summary><div v-if="cluster" class="replicate-line" v-for="g in groups" :key="g.core"><strong>{{g.core}}</strong><span>{{g.specimen_count}} 试样 / {{g.specimen_references.join('、')}}</span></div><div class="replicate-line" v-for="r in (cluster?preview:bootstrap.replicates.slice(0,16))" :key="r.repeat"><strong>#{{r.repeat}} {{r.valid?fmt(r.kappa,6):'未定义'}}</strong><span v-if="cluster">{{multiplicity(r)}} → {{r.drawn_specimen_count}} 试样（{{r.distinct_core_count}} 个不同岩芯）/ {{r.reason||'有效'}}</span><span v-else>{{r.reason||'有效'}} / 抽取行 {{r.sample_indices.slice(0,12).join(', ')}}{{r.sample_indices.length>12?' …':''}}</span></div></details></section></template>
